package application.adapters.persistence.jpa.entities;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * JPA persistence entity for Cart.
 */
@Entity
@Table(name = "carts")
@Getter
@Setter
@NoArgsConstructor
public class CartJpaEntity {

    /** Cart.identifier (decision D2), generated by the adapter. */
    @Id
    @Column(name = "identifier", nullable = false, length = 60)
    private String identifier;

    /** Cart.buyer reference. */
    @Column(name = "buyer_identifier", nullable = false, length = 60)
    private String buyerIdentifier;

    /** CartStatus enum name. */
    @Column(name = "status", length = 20)
    private String status;
}
